// Generated from documented common reference; no class-specific prices.
export const POWER_WEIGHTS={"atk":4.9988,"hp":0.4999,"def":36.1182,"crit":679509.5159,"critd":90867.8061,"amp":194679.0156,"haste":119683.2782,"pen":350.9834,"acc":62.3059,"dr":107.8315,"cdr":332207.0291,"critres":461580.3655,"critdres":133969.9275,"ampres":302727.3645,"ten":100000,"pvp":250000,"ignoreAmpRes":194679.0156,"ignoreCritRes":679509.5159};
export function powerScore(st,classId,level){const magic=classId==='ARC',hybrid=classId==='LAS',values={atk:magic?st.am:st.af,hp:st.hp,def:st.def,crit:st.crit,critd:Math.max(0,st.critd-1.2),amp:hybrid?(st.ampF+st.ampM)/2:magic?st.ampM:st.ampF,haste:st.haste,pen:hybrid?(st.penF+st.penM)/2:magic?st.penM:st.penF,acc:st.acc,dr:st.dr,cdr:st.cdr,critres:st.critres,critdres:Math.min(1,st.critdres),ampres:Math.min(.8,st.ampres),ten:st.ten,pvp:st.pvp,ignoreAmpRes:st.ignoreAmpRes,ignoreCritRes:st.ignoreCritRes};return Math.round(level*100+Object.entries(values).reduce((sum,[k,v])=>sum+Math.max(0,v)*POWER_WEIGHTS[k],0));}
